package cn.voidhaven.api.web;
import cn.voidhaven.api.persistence.AccountRepository;
import cn.voidhaven.api.service.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.constraints.Size;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import org.springframework.security.core.Authentication;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
import java.util.*;
@RestController @RequestMapping("/api/v1/admin")
public class AdminController {
    private final ContentManagementService content; private final IdempotencyService idempotency; private final AccountRepository accounts; private final PartnerAccountProvisioningService provisioning; private final PartnerAdministrationService partnerAdministration; private final AuditQueryService auditQuery;
    public AdminController(ContentManagementService content, IdempotencyService idempotency, AccountRepository accounts, PartnerAccountProvisioningService provisioning, PartnerAdministrationService partnerAdministration, AuditQueryService auditQuery) { this.content = content; this.idempotency = idempotency; this.accounts = accounts; this.provisioning = provisioning; this.partnerAdministration = partnerAdministration; this.auditQuery = auditQuery; }
    record ReviewDecision(String decision, @Size(max = 1000) String reason) { }
    record ActionReason(@Size(max = 1000) String reason) { }
    record ApprovePartnerApplication(@NotBlank @Pattern(regexp = "[A-Za-z0-9._-]{4,100}") String loginId) { }
    record QuotaChange(@jakarta.validation.constraints.Min(0) @jakarta.validation.constraints.Max(5) int quota, @NotBlank @Size(max = 1000) String reason) { }
    record OwnershipTransfer(@NotBlank String contentItemId, @NotBlank String toPartnerProfileId, @NotBlank @Size(max = 1000) String reason) { }
    record OwnershipTransferred(String contentItemId, String toPartnerProfileId) { }
    @GetMapping("/review-queue") ApiResponse<List<ContentManagementService.Managed>> queue(HttpServletRequest req) { return ok(content.pending(), req); }
    @GetMapping("/content-items") ApiResponse<List<ContentManagementService.Managed>> contentItems(HttpServletRequest req) { return ok(content.allManaged(), req); }
    @GetMapping("/partner-applications") ApiResponse<List<PartnerAccountProvisioningService.PendingApplication>> partnerApplications(HttpServletRequest req) { return ok(provisioning.pendingApplications(), req); }
    @GetMapping("/partner-profiles") ApiResponse<List<PartnerAdministrationService.ProfileView>> partnerProfiles(HttpServletRequest req) { return ok(partnerAdministration.listProfiles(), req); }
    @GetMapping("/audit-logs") ApiResponse<List<AuditQueryService.Entry>> auditLogs(@RequestParam(defaultValue = "30") int limit, HttpServletRequest req) { return ok(auditQuery.recent(limit), req); }
    @PostMapping("/content-items") ApiResponse<ContentManagementService.Managed> create(@RequestHeader("Idempotency-Key") String key, @jakarta.validation.Valid @RequestBody ContentManagementService.Draft draft, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, draft, ContentManagementService.Managed.class, () -> content.create(draft, null, accountId(auth), role(auth), requestId(req))), req); }
    @PatchMapping("/content-items/{id}") ApiResponse<ContentManagementService.Managed> revise(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @RequestHeader("If-Match") String version, @jakarta.validation.Valid @RequestBody ContentManagementService.Draft draft, Authentication auth, HttpServletRequest req) { long expected = version(version); return ok(idempotency.execute(key, Map.of("id", id, "version", expected, "draft", draft), ContentManagementService.Managed.class, () -> content.revise(id, draft, null, expected, accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/content-items/{id}/submit-review") ApiResponse<ContentManagementService.Managed> submit(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "action", "SUBMIT"), ContentManagementService.Managed.class, () -> content.submitAsAdmin(id, accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/reviews/{id}/decision") ApiResponse<ContentManagementService.Managed> decide(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @RequestBody ReviewDecision decision, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "decision", decision.decision(), "reason", String.valueOf(decision.reason())), ContentManagementService.Managed.class, () -> content.decide(id, decision.decision(), decision.reason(), accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/content-items/{id}/publish") ApiResponse<ContentManagementService.Managed> publish(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "action", "PUBLISH"), ContentManagementService.Managed.class, () -> content.publish(id, accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/content-items/{id}/hide") ApiResponse<ContentManagementService.Managed> hide(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @RequestBody ActionReason action, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "action", "HIDE", "reason", String.valueOf(action.reason())), ContentManagementService.Managed.class, () -> content.hide(id, action.reason(), accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/content-items/{id}/show") ApiResponse<ContentManagementService.Managed> show(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "action", "SHOW"), ContentManagementService.Managed.class, () -> content.show(id, accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/content-items/{id}/archive") ApiResponse<ContentManagementService.Managed> archive(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @RequestBody ActionReason action, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "action", "ARCHIVE", "reason", String.valueOf(action.reason())), ContentManagementService.Managed.class, () -> content.archive(id, action.reason(), accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/content-items/{id}/restore") ApiResponse<ContentManagementService.Managed> restore(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @RequestBody ActionReason action, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "action", "RESTORE", "reason", String.valueOf(action.reason())), ContentManagementService.Managed.class, () -> content.restore(id, action.reason(), accountId(auth), role(auth), requestId(req))), req); }
    @PreAuthorize("hasRole('SUPER_ADMIN')") @PostMapping("/content-items/{id}/delete") ApiResponse<ContentManagementService.Managed> delete(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @RequestBody ActionReason action, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "action", "DELETE", "reason", String.valueOf(action.reason())), ContentManagementService.Managed.class, () -> content.delete(id, action.reason(), accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/partner-applications/{id}/approve") ApiResponse<PartnerAccountProvisioningService.Provisioned> approvePartnerApplication(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @jakarta.validation.Valid @RequestBody ApprovePartnerApplication body, Authentication auth, HttpServletRequest req) { return ok(idempotency.executeSingleDelivery(key, Map.of("id", id, "loginId", body.loginId()), () -> provisioning.approveApplication(id, body.loginId(), accountId(auth), role(auth), requestId(req))), req); }
    @PatchMapping("/partner-profiles/{id}/content-quota") ApiResponse<PartnerAdministrationService.ProfileView> setQuota(@PathVariable String id, @RequestHeader("Idempotency-Key") String key, @jakarta.validation.Valid @RequestBody QuotaChange body, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, Map.of("id", id, "quota", body.quota(), "reason", body.reason()), PartnerAdministrationService.ProfileView.class, () -> partnerAdministration.setQuota(id, body.quota(), body.reason(), accountId(auth), role(auth), requestId(req))), req); }
    @PostMapping("/content-ownership-transfers") ApiResponse<OwnershipTransferred> transferOwnership(@RequestHeader("Idempotency-Key") String key, @jakarta.validation.Valid @RequestBody OwnershipTransfer body, Authentication auth, HttpServletRequest req) { return ok(idempotency.execute(key, body, OwnershipTransferred.class, () -> { partnerAdministration.transferOwnership(body.contentItemId(), body.toPartnerProfileId(), body.reason(), accountId(auth), role(auth), requestId(req)); return new OwnershipTransferred(body.contentItemId(), body.toPartnerProfileId()); }), req); }
    private long version(String value) { try { return Long.parseLong(value.replace("\"", "")); } catch (NumberFormatException error) { throw new ApiException(org.springframework.http.HttpStatus.BAD_REQUEST, "CONTENT_VERSION_REQUIRED", "请携带有效的内容版本后重试。"); } } private String accountId(Authentication auth) { return accounts.findByLoginId(auth.getName()).filter(account -> account.isActive()).orElseThrow(() -> new ApiException(org.springframework.http.HttpStatus.UNAUTHORIZED, "ACCOUNT_INACTIVE", "当前账号已停用或资格不可用。" )).getId(); } private String role(Authentication auth) { return auth.getAuthorities().stream().findFirst().map(value -> value.getAuthority().replaceFirst("^ROLE_", "")).orElse("ADMIN"); } private <T> ApiResponse<T> ok(T data, HttpServletRequest req) { return new ApiResponse<>(data, requestId(req)); } private String requestId(HttpServletRequest req) { return (String) req.getAttribute(RequestIdFilter.ATTRIBUTE); }
}
